SELECT dept_name AS deptName, NVL(SUM(tui_hao_shu), 0) AS refundCount, ROUND(NVL(SUM(tui_hao_shu), 0) / NULLIF(SUM(total_guahao), 0) * 100, 2) || '%' AS refundRate, NVL(SUM(shuang_yue_shu), 0) AS noShowCount, ROUND(NVL(SUM(shuang_yue_shu), 0) / NULLIF(SUM(total_guahao), 0) * 100, 2) || '%' AS noShowRate FROM TR_OUTPATIENT_STATS_DAY_RESULT WHERE stats_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY refundCount DESC

SELECT '0-14' AS ageGroup, NVL(SUM(tui_hao_age_0_14), 0) AS refundCount, NVL(SUM(shuang_yue_age_0_14), 0) AS noShowCount FROM TR_OUTPATIENT_STATS_DAY_RESULT WHERE stats_date BETWEEN #{startDate} AND #{endDate}
UNION ALL
